export class GameController {
  private gameEngine: GameEngine;
  private gameState: GameState;
  private aiOpponent: AIOpponent;
  private renderView: RenderView;

  constructor() {
    this.gameEngine = new GameEngine();
    this.gameState = new GameState();
    this.aiOpponent = new AIOpponent();
    this.renderView = new RenderView();
  }

  startGame(): void {
    this.gameState.init();
    this.gameEngine.start();
    this.aiOpponent.start();
    this.renderView.render();
  }

  stopGame(): void {
    this.gameEngine.stop();
    this.aiOpponent.stop();
    this.renderView.clear();
  }

  processInput(input: string): void {
    if (input === 'w') {
      this.gameState.ship.moveUp();
    } else if (input === 's') {
      this.gameState.ship.moveDown();
    } else if (input === 'a') {
      this.gameState.ship.moveLeft();
    } else if (input === 'd') {
      this.gameState.ship.moveRight();
    } else if (input === ' ') {
      this.gameState.ship.fireBullet();
    } else if (input === 'q') {
      this.stopGame();
    }
  }
}

