export class GameState {
  private ship: { position: { x: number; y: number }; velocity: { x: number; y: number }; angle: number; health: number; bullets: { position: { x: number; y: number }; velocity: { x: number; y: number }; angle: number; damage: number }[] };
  private asteroids: { position: { x: number; y: number }; velocity: { x: number; y: number }; size: number; health: number }[];
  private bullets: { position: { x: number; y: number }; velocity: { x: number; y: number }; angle: number; damage: number; lifespan: number }[];
  private score: number;
  private highScore: number;
  private gameRunning: boolean;

  constructor() {
    this.ship = { position: { x: 0, y: 0 }, velocity: { x: 0, y: 0 }, angle: 0, health: 100, bullets: [] };
    this.asteroids = [];
    this.bullets = [];
    this.score = 0;
    this.highScore = 0;
    this.gameRunning = true;
  }

  init() {
    this.ship.position.x = 0;
    this.ship.position.y = 0;
    this.ship.velocity.x = 0;
    this.ship.velocity.y = 0;
    this.ship.angle = 0;
    this.ship.health = 100;
    this.ship.bullets = [];
    this.asteroids = [];
    this.bullets = [];
    this.score = 0;
    this.highScore = 0;
    this.gameRunning = true;
  }

  update(dt: number) {
    this.ship.update(dt);
    this.asteroids.forEach((asteroid) => {
      asteroid.position.x += asteroid.velocity.x * dt;
      asteroid.position.y += asteroid.velocity.y * dt;
      if (asteroid.position.x < -100 || asteroid.position.x > 800 || asteroid.position.y < -100 || asteroid.position.y > 600) {
        this.asteroids.splice(this.asteroids.indexOf(asteroid), 1);
      }
    });
    this.bullets.forEach((bullet) => {
      bullet.position.x += bullet.velocity.x * dt;
      bullet.position.y += bullet.velocity.y * dt;
      if (bullet.position.x < -100 || bullet.position.x > 800 || bullet.position.y < -100 || bullet.position.y > 600) {
        this.bullets.splice(this.bullets.indexOf(bullet), 1);
      }
    });
  }

  render() {
    // Render the game state
  }

  handleInput(input: string) {
    if (input === 'w') {
      this.ship.moveUp();
    } else if (input === 's') {
      this.ship.moveDown();
    } else if (input === 'a') {
      this.ship.moveLeft();
    } else if (input === 'd') {
      this.ship.moveRight();
    } else if (input === ' ') {
      this.ship.fireBullet();
    }
  }
}

