export function renderAsteroidField() {
    const belt = document.getElementById('belt');
    if (!belt) return;
    belt.innerHTML = '';
    for (let i = 0; i < 30; i++) {
        const a = document.createElement('div');
        a.className = 'asteroid';
        a.style.left = (Math.random() * 800).toString() + '%';
        a.style.top = (Math.random() * 600).toString() + '%';
        a.style.transform = 'rotate(' + (Math.random() * 360).toString() + 'deg)';
        a.style.transformScale = (Math.random() * 0.5 + 0.5).toString();
        belt.appendChild(a);
    }
}

export function renderShip(ship) {
    const shipEl = document.getElementById('ship');
    if (!shipEl) return;
    shipEl.style.transform = 'translate(' + ship.x + 'px,' + ship.y + 'px) rotate(' + ship.angle + 'deg)';
    shipEl.style.opacity = ship.health / 100;
}

export function renderBullets(bullets) {
    const belt = document.getElementById('belt');
    if (!belt) return;
    belt.innerHTML = '';
    for (const b of bullets) {
        const bullet = document.createElement('div');
        bullet.className = 'bullet';
        bullet.style.left = b.x + 'px';
        bullet.style.top = b.y + 'px';
        belt.appendChild(bullet);
    }
}

export function renderAsteroids(asteroids) {
    const belt = document.getElementById('belt');
    if (!belt) return;
    belt.innerHTML = '';
    for (const a of asteroids) {
        const asteroid = document.createElement('div');
        asteroid.className = 'asteroid';
        asteroid.style.left = a.x + 'px';
        asteroid.style.top = a.y + 'px';
        asteroid.style.transform = 'rotate(' + a.angle + 'deg)';
        asteroid.style.transformScale = a.size.toString();
        belt.appendChild(asteroid);
    }
}

export function renderScore(score, highScore) {
    document.getElementById('scoreDisplay').textContent = 'Score: ' + score + ' | High Score: ' + highScore;
}

export function renderLives(lives) {
    const livesDisplay = document.getElementById('livesDisplay');
    if (!livesDisplay) return;
    livesDisplay.innerHTML = '';
    for (let i = 0; i < lives; i++) {
        const life = document.createElement('div');
        life.className = 'life';
        livesDisplay.appendChild(life);
    }
}
